hl.on("hyprland.start", function()
    hl.exec_cmd("waybar")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("batsignal -w 20 -c 10 -n BAT0")
    hl.exec_cmd("udiskie -s -f lf")
    hl.exec_cmd("fusuma -d")
    hl.exec_cmd("copyq --start-server")
    hl.exec_cmd("nm-applet")
    hl.exec_cmd("blueman-applet & dbus-update-activation-environment DISPLAY")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("while true; do rclone --max-depth 0 --rc --vfs-cache-mode off --transfers=128 -o blocksize=1048576 --file-perms 766 mount storagebox-webdav: /mnt/storagebox --allow-other --links; done")
end)


